/**
 * RFC 6238 TOTP (SHA-1, 6 digits, 30-second steps) implemented locally.
 *
 * Dependency-free on purpose: this is a small, static algorithm and the
 * platform security boundary should not grow a transitive dependency tree for
 * it. Base32 parsing accepts the alphabet generated by `generateTotpSecret`.
 */

import crypto from 'node:crypto';

const BASE32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const DEFAULT_STEP_SECONDS = 30;
const DEFAULT_DIGITS = 6;
const DEFAULT_WINDOW = 1;

export type TotpVerification = {
  valid: boolean;
  counter: number;
  matchedStep: number;
};

function sanitizeBase32(secret: string): string {
  return String(secret || '')
    .toUpperCase()
    .replace(/[\s-]/g, '')
    .replace(/=+$/, '');
}

export function base32Encode(buffer: Buffer): string {
  let bits = 0;
  let value = 0;
  let output = '';
  for (const byte of buffer) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      output += BASE32_ALPHABET[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) {
    output += BASE32_ALPHABET[(value << (5 - bits)) & 31];
  }
  return output;
}

export function base32Decode(secret: string): Buffer {
  const normalized = sanitizeBase32(secret);
  if (!normalized || /[^A-Z2-7]/.test(normalized)) {
    throw new Error('Invalid TOTP secret');
  }
  let bits = 0;
  let value = 0;
  const bytes: number[] = [];
  for (const character of normalized) {
    value = (value << 5) | BASE32_ALPHABET.indexOf(character);
    bits += 5;
    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 255);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
}

export function generateTotpSecret(bytes = 20): string {
  return base32Encode(crypto.randomBytes(bytes));
}

export function currentTotpCounter(nowMs = Date.now(), stepSeconds = DEFAULT_STEP_SECONDS): number {
  return Math.floor(nowMs / 1000 / stepSeconds);
}

export function generateTotp(
  secret: string,
  counter: number,
  digits = DEFAULT_DIGITS,
): string {
  const key = base32Decode(secret);
  const counterBuffer = Buffer.alloc(8);
  counterBuffer.writeBigUInt64BE(BigInt(counter));
  const digest = crypto.createHmac('sha1', key).update(counterBuffer).digest();
  const offset = digest[digest.length - 1]! & 0x0f;
  const binary =
    ((digest[offset]! & 0x7f) << 24) |
    ((digest[offset + 1]! & 0xff) << 16) |
    ((digest[offset + 2]! & 0xff) << 8) |
    (digest[offset + 3]! & 0xff);
  return String(binary % 10 ** digits).padStart(digits, '0');
}

/**
 * Verify a six-digit TOTP. A `lastUsedCounter` prevents replaying a code that
 * was already accepted. The window is symmetric (one step before and after)
 * to tolerate clock skew.
 */
export function verifyTotp(
  secret: string,
  token: string,
  options: {
    nowMs?: number;
    window?: number;
    lastUsedCounter?: number;
    stepSeconds?: number;
    digits?: number;
  } = {},
): TotpVerification {
  const normalized = String(token || '').replace(/\s/g, '');
  const digits = options.digits ?? DEFAULT_DIGITS;
  if (!new RegExp(`^\\d{${digits}}$`).test(normalized)) {
    return { valid: false, counter: -1, matchedStep: 0 };
  }
  const stepSeconds = options.stepSeconds ?? DEFAULT_STEP_SECONDS;
  const nowCounter = currentTotpCounter(options.nowMs ?? Date.now(), stepSeconds);
  const window = options.window ?? DEFAULT_WINDOW;
  const candidates: number[] = [];
  for (let offset = -window; offset <= window; offset += 1) {
    candidates.push(nowCounter + offset);
  }
  for (const counter of candidates) {
    if (
      typeof options.lastUsedCounter === 'number' &&
      Number.isFinite(options.lastUsedCounter) &&
      counter <= options.lastUsedCounter
    ) {
      continue;
    }
    const expected = generateTotp(secret, counter, digits);
    const supplied = Buffer.from(normalized);
    const comparison = Buffer.from(expected);
    if (
      supplied.length === comparison.length &&
      crypto.timingSafeEqual(supplied, comparison)
    ) {
      return { valid: true, counter, matchedStep: counter - nowCounter };
    }
  }
  return { valid: false, counter: -1, matchedStep: 0 };
}

export function totpUri(params: {
  secret: string;
  accountName: string;
  issuer?: string;
  digits?: number;
  stepSeconds?: number;
}): string {
  const issuer = params.issuer || 'Inventory AI Platform';
  const label = encodeURIComponent(`${issuer}:${params.accountName}`);
  const query = new URLSearchParams({
    secret: sanitizeBase32(params.secret),
    issuer,
    algorithm: 'SHA1',
    digits: String(params.digits ?? DEFAULT_DIGITS),
    period: String(params.stepSeconds ?? DEFAULT_STEP_SECONDS),
  });
  return `otpauth://totp/${label}?${query.toString()}`;
}

export default {
  base32Encode,
  base32Decode,
  generateTotpSecret,
  currentTotpCounter,
  generateTotp,
  verifyTotp,
  totpUri,
};
